import{_ as t,o as a,a as r,a2 as s}from"./chunks/framework.DCcmcJcL.js";const g=JSON.parse('{"title":"Before You Start","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/before-you-start.md","filePath":"getting-started/before-you-start.md","lastUpdated":1790143103000}'),o={name:"getting-started/before-you-start.md"};function i(n,e,l,d,h,c){return a(),r("div",null,e[0]||(e[0]=[s(`<h1 id="before-you-start" tabindex="-1">Before You Start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before You Start&quot;">​</a></h1><p>Bagisto is a Laravel application, so working on Bagisto means working in Laravel. This page lists what helps to know before you begin, and what your machine needs to run Bagisto.</p><h2 id="what-to-know-first" tabindex="-1">What to Know First <a class="header-anchor" href="#what-to-know-first" aria-label="Permalink to &quot;What to Know First&quot;">​</a></h2><p>You can install Bagisto without deep Laravel experience, but extending it means writing Laravel code. These topics come up on almost every page.</p><h3 id="php" tabindex="-1">PHP <a class="header-anchor" href="#php" aria-label="Permalink to &quot;PHP&quot;">​</a></h3><ul><li><a href="https://www.php.net/manual/en/langref.php" target="_blank" rel="noreferrer">Core PHP concepts</a>: variables, functions, arrays and control structures</li><li><a href="https://www.php.net/manual/en/language.namespaces.php" target="_blank" rel="noreferrer">Namespaces</a> and <a href="https://www.php.net/manual/en/language.oop5.autoload.php" target="_blank" rel="noreferrer">autoloading</a>, including the <a href="https://www.php-fig.org/psr/psr-4/" target="_blank" rel="noreferrer">PSR-4 standard</a></li><li><a href="https://www.php.net/manual/en/language.oop5.php" target="_blank" rel="noreferrer">Object-oriented PHP</a></li><li><a href="https://getcomposer.org/doc/01-basic-usage.md" target="_blank" rel="noreferrer">Composer</a> for dependencies</li></ul><h3 id="laravel" tabindex="-1">Laravel <a class="header-anchor" href="#laravel" aria-label="Permalink to &quot;Laravel&quot;">​</a></h3><ul><li><a href="https://laravel.com/docs/routing" target="_blank" rel="noreferrer">Routing</a> and <a href="https://laravel.com/docs/controllers" target="_blank" rel="noreferrer">controllers</a></li><li>The <a href="https://laravel.com/docs/container" target="_blank" rel="noreferrer">service container</a> and <a href="https://laravel.com/docs/providers" target="_blank" rel="noreferrer">service providers</a></li><li><a href="https://laravel.com/docs/middleware" target="_blank" rel="noreferrer">Middleware</a></li><li><a href="https://laravel.com/docs/events" target="_blank" rel="noreferrer">Events and listeners</a></li><li><a href="https://laravel.com/docs/eloquent" target="_blank" rel="noreferrer">Eloquent</a> and <a href="https://laravel.com/docs/migrations" target="_blank" rel="noreferrer">migrations</a></li><li><a href="https://laravel.com/docs/blade" target="_blank" rel="noreferrer">Blade templates</a></li></ul><p>Bagisto 2.5 runs on Laravel 13; Bagisto 2.4 runs on Laravel 12. The concepts above are the same on both.</p><h3 id="front-end" tabindex="-1">Front End <a class="header-anchor" href="#front-end" aria-label="Permalink to &quot;Front End&quot;">​</a></h3><p>You need these only when you change how the admin or the storefront looks:</p><ul><li><a href="https://vuejs.org/guide/introduction.html" target="_blank" rel="noreferrer">Vue.js 3</a></li><li><a href="https://tailwindcss.com/docs/installation" target="_blank" rel="noreferrer">Tailwind CSS</a>, version 4 (Bagisto 2.4 uses version 3)</li><li><a href="https://laravel.com/docs/vite" target="_blank" rel="noreferrer">Vite</a></li></ul><h3 id="where-to-ask" tabindex="-1">Where to Ask <a class="header-anchor" href="#where-to-ask" aria-label="Permalink to &quot;Where to Ask&quot;">​</a></h3><ul><li><a href="https://github.com/bagisto/bagisto" target="_blank" rel="noreferrer">Bagisto on GitHub</a>: code, issues and pull requests</li><li><a href="https://forums.bagisto.com/" target="_blank" rel="noreferrer">Bagisto forums</a>: questions and community discussion</li></ul><h2 id="system-requirements" tabindex="-1">System Requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Software</th><th>Version</th><th>Notes</th></tr></thead><tbody><tr><td>PHP</td><td>8.4</td><td><code>composer.json</code> requires <code>^8.4</code>, and CI runs on 8.4. Bagisto 2.4 runs on PHP 8.3 or 8.4.</td></tr><tr><td>Composer</td><td>2</td><td></td></tr><tr><td>Database</td><td>MySQL 8.0, MariaDB 10.11 or PostgreSQL 16</td><td>CI tests all three. Bagisto 2.4 doesn&#39;t support PostgreSQL.</td></tr><tr><td>Web server</td><td>Nginx, Apache or OpenLiteSpeed</td><td>Not needed on your own machine, where <code>php artisan serve</code> is enough.</td></tr><tr><td>Node.js</td><td>22</td><td>Only to rebuild the admin, storefront or installer assets, to run the Playwright end-to-end tests, or to use <code>php artisan dev</code>. CI uses Node.js 22.13.1.</td></tr></tbody></table><p>Check what your machine has:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span></code></pre></div><h3 id="php-extensions" tabindex="-1">PHP Extensions <a class="header-anchor" href="#php-extensions" aria-label="Permalink to &quot;PHP Extensions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Needed by</th><th>Extensions</th></tr></thead><tbody><tr><td><code>composer.json</code></td><td><code>calendar</code>, <code>curl</code>, <code>intl</code>, <code>mbstring</code>, <code>openssl</code>, <code>pdo</code>, <code>pdo_mysql</code>, <code>tokenizer</code></td></tr><tr><td>The web installer&#39;s requirements screen (<code>packages/Webkul/Installer/src/Helpers/ServerRequirements.php</code>)</td><td>Also <code>ctype</code>, <code>dom</code>, <code>fileinfo</code>, <code>filter</code>, <code>gd</code>, <code>hash</code>, <code>json</code>, <code>pcre</code>, <code>session</code>, <code>xml</code></td></tr><tr><td>Composer dependencies, which some PHP builds leave out</td><td><code>bcmath</code>, <code>iconv</code>, <code>libxml</code>, <code>simplexml</code>, <code>xmlreader</code>, <code>xmlwriter</code>, <code>zip</code>, <code>zlib</code></td></tr><tr><td>PostgreSQL</td><td><code>pdo_pgsql</code></td></tr><tr><td><code>IMAGE_DRIVER=imagick</code> (the default driver in <code>config/images.php</code> is <code>gd</code>)</td><td><code>imagick</code></td></tr><tr><td><code>REDIS_CLIENT=phpredis</code>, the value in <code>.env.example</code></td><td><code>redis</code>. Set <code>REDIS_CLIENT=predis</code> to use the <code>predis/predis</code> library instead, which Bagisto already requires.</td></tr></tbody></table><p><code>composer install</code> stops and names any extension that is missing.</p><h3 id="php-settings" tabindex="-1">PHP Settings <a class="header-anchor" href="#php-settings" aria-label="Permalink to &quot;PHP Settings&quot;">​</a></h3><p>Bagisto doesn&#39;t check <code>php.ini</code> values. The production Docker image ships these, which are a sensible starting point for a store:</p><p><strong>File:</strong> <code>docker/production/shared/php.ini</code></p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">memory_limit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 512M</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">upload_max_filesize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 100M</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">post_max_size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 110M</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">max_execution_time</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 300</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">max_input_time</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 300</span></span></code></pre></div><h3 id="optional-services" tabindex="-1">Optional Services <a class="header-anchor" href="#optional-services" aria-label="Permalink to &quot;Optional Services&quot;">​</a></h3><ul><li><strong>Elasticsearch 8</strong> for catalog search on larger stores. Bagisto requires the <code>elasticsearch/elasticsearch</code> client <code>^8.10</code>. See <a href="./../performance/configure-elasticsearch.html">Configure Elasticsearch</a>.</li><li><strong>Redis</strong> for the cache, session, queue and full page cache stores. See <a href="./../advanced/cache-strategy.html">Cache Strategy</a>.</li><li><strong>Amazon S3 or Cloudflare R2</strong> for media files. See <a href="./../advanced/file-storage.html">File Storage</a>.</li></ul><h2 id="next-step" tabindex="-1">Next Step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next Step&quot;">​</a></h2><p><a href="./installation.html">Install Bagisto</a>.</p>`,29)]))}const u=t(o,[["render",i]]);export{g as __pageData,u as default};
